package com.crms.entity;
import com.crms.enums.Role;import jakarta.persistence.*;import jakarta.validation.constraints.*;import java.time.Instant;
@Entity @Table(name="users",uniqueConstraints=@UniqueConstraint(columnNames="email")) public class User{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@NotBlank private String name;@Email @NotBlank private String email;@NotBlank private String password;@Enumerated(EnumType.STRING) @NotNull private Role role;private boolean enabled=true;private Instant createdAt=Instant.now();public Long getId(){return id;}public String getName(){return name;}public void setName(String v){name=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getPassword(){return password;}public void setPassword(String v){password=v;}public Role getRole(){return role;}public void setRole(Role v){role=v;}public boolean isEnabled(){return enabled;}}
